Lemma gl_B : forall (fx : FPState) regs (m : word -> option byte) (s pa : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (4096 <= pa)%Z ->
  (pa + 32 <= s - 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 52)) 4 = Some (Z_to_le_bytes 4 1) ->
  rdn SEGS m (Z_to_bv 64 pa) 4 = Some (Z_to_le_bytes 4 10) ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 8 = Z_to_bv 64 pa ->
  getr regs 18 = Z_to_bv 64 0 ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 100920) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 194260) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 100952 /\ getr regs' 10 = Z_to_bv 64 10 /\ getr regs' 11 = Z_to_bv 64 8 /\ getr regs' 9 = Z_to_bv 64 10 /\
      regs_agree (fun r => In r [1; 9; 10; 11]%list) regs regs').
Proof.
