Lemma gl_C : forall (fx : FPState) regs (m : word -> option byte) (s ls : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (4096 <= ls < 2 ^ 47)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 ls ->
  getr regs 9 = Z_to_bv 64 10 ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 100952) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 100972) M' rom /\
      M' = m /\ getr regs' 18 = Z_to_bv 64 0 /\ getr regs' 19 = Z_to_bv 64 ls /\ getr regs' 20 = Z_to_bv 64 ls /\
      regs_agree (fun r => In r [18; 19; 20]%list) regs regs').
