Lemma gl_E_last : forall (fx : FPState) regs (m : word -> option byte) (s lsi pix lines i ls : Z),
  (4096 + 128 <= s <= 2 ^ 47)%Z ->
  (4096 <= lsi)%Z ->
  (lsi + 8 <= s - 128)%Z ->
  (4096 <= pix)%Z ->
  (pix + 64 <= s - 128)%Z ->
  (pix mod 16 = 0)%Z ->
  (0 <= lines < 2 ^ 47)%Z ->
  (0 <= i < 10)%Z ->
  (i + 1 = 10)%Z ->
  (0 <= ls < 2 ^ 47)%Z ->
  (pix + 64 <= lsi \/ lsi + 8 <= pix)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 64)) 8 = Some (Z_to_le_bytes 8 pix) ->
  rdn SEGS m (Z_to_bv 64 (pix + 20)) 4 = Some (Z_to_le_bytes 4 2) ->
  store_ok SEGS m (Z_to_bv 64 (s - 128)) 128 = true ->
  store_ok SEGS m (Z_to_bv 64 (pix + 20)) 4 = true ->
  store_ok SEGS m (Z_to_bv 64 lsi) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 lines ->
  getr regs 20 = Z_to_bv 64 lsi ->
  getr regs 18 = Z_to_bv 64 i ->
  getr regs 9 = Z_to_bv 64 10 ->
  getr regs 19 = Z_to_bv 64 ls ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 101000) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 101196) M' rom /\
      rinv [((s - 128)%Z, 72%Z); (lsi, 8%Z); ((pix + 20)%Z, 4%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 lsi) 8 = Some (Z_to_le_bytes 8 lines) /\
      rdn SEGS M' (Z_to_bv 64 (pix + 20)) 4 = Some (Z_to_le_bytes 4 1) /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\
      getr regs' 10 = Z_to_bv 64 ls /\
